style.css:
@-moz-document domain("roblox.com") {
/* Фон страницы — обязательно url("...") */
    body {
        background: url("https://imgur.la/image/WhatsApp-Image-2025-08-10-at-17%2C28%2C14-Picsart-AiImageEnhancer.6VMjcp") no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: #000 !important; /* запасной цвет, пока картинка не загрузится */
    }

    .container-main, 
    .content {
        background-color: rgba(255, 255, 255, 0.85) !important;
    }

    .rbx-navbar {
        background-color: rgba(0, 0, 0, 0.6) !important;
    }

    .btn-primary {
        background-color: #ff5a5f !important;
        border-color: #ff5a5f !important;
    }
    .btn-primary:hover {
        background-color: #ff787c !important;
        border-color: #ff787c !important;
    }

    body, .text-label, .text, a {
        color: #ffffff !important;
    }
}
